[{"order":1,"type":"heading","text":"Spring Data MongoDB: Working with NoSQL Databases"},{"order":2,"type":"paragraph","text":"Spring Data MongoDB provides a powerful and convenient way to interact with MongoDB databases within Spring Boot applications. It simplifies data access by abstracting away much of the boilerplate code typically associated with database interactions. This tutorial will guide you through setting up Spring Data MongoDB, defining data models, performing CRUD operations, and exploring advanced features."},{"order":3,"type":"heading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Java Development Kit (JDK) 8 or higher"},{"order":5,"type":"bullet_point","text":"Maven or Gradle build tool"},{"order":6,"type":"bullet_point","text":"MongoDB installed and running"},{"order":7,"type":"bullet_point","text":"Basic understanding of Spring Boot"},{"order":8,"type":"heading","text":"Setting up a Spring Boot Project"},{"order":9,"type":"paragraph","text":"You can create a new Spring Boot project using Spring Initializr (start.spring.io). Add the 'Spring Data MongoDB' dependency. You can also include 'Spring Web' if you plan to expose your data through REST APIs."},{"order":10,"type":"paragraph","text":"Here's a sample `pom.xml` (Maven) configuration:"},{"order":11,"type":"code","text":"<?xml version="1.0" encoding="UTF-8"?>
<project xmlns="http://maven.apache.org/POM/4.0.0" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
	xsi:schemaLocation="http://maven.apache.org/POM/4.0.0 https://maven.apache.org/xsd/maven-4.0.0.xsd">
	<modelVersion>4.0.0</modelVersion>
	<parent>
		<groupId>org.springframework.boot</groupId>
		<artifactId>spring-boot-starter-parent</artifactId>
		<version>3.2.0</version>
		<relativePath/> <!-- lookup parent from repository -->
	</parent>
	<groupId>com.example</groupId>
	<artifactId>spring-data-mongodb-example</artifactId>
	<version>0.0.1-SNAPSHOT</version>
	<name>spring-data-mongodb-example</name>
	<description>Spring Data MongoDB Example</description>
	<properties>
		<java.version>17</java.version>
	</properties>
	<dependencies>
		<dependency>
			<groupId>org.springframework.boot</groupId>
			<artifactId>spring-boot-starter-data-mongodb</artifactId>
		</dependency>
		<dependency>
			<groupId>org.springframework.boot</groupId>
			<artifactId>spring-boot-starter-web</artifactId>
		</dependency>

		<dependency>
			<groupId>org.springframework.boot</groupId>
			<artifactId>spring-boot-starter-test</artifactId>
			<scope>test</scope>
		</dependency>
	</dependencies>

	<build>
		<plugins>
			<plugin>
				<groupId>org.springframework.boot</groupId>
				<artifactId>spring-boot-maven-plugin</artifactId>
			</plugin>
		</plugins>
	</build>

</project>"},{"order":12,"type":"paragraph","text":"For Gradle, here's a sample `build.gradle.kts` configuration:"},{"order":13,"type":"code","text":"plugins {
	id("java")
	id("org.springframework.boot") version "3.2.0"
	id("io.spring.dependency-management") version "1.1.4"
}

group = "com.example"
version = "0.0.1-SNAPSHOT"
sourceCompatibility = JavaVersion.VERSION_17

repositories {
	mavenCentral()
}

dependencies {
	implementation("org.springframework.boot:spring-boot-starter-data-mongodb")
	implementation("org.springframework.boot:spring-boot-starter-web")
	testImplementation("org.springframework.boot:spring-boot-starter-test")
}

tasks.withType<Test> {
	useJUnitPlatform()
}"},{"order":14,"type":"heading","text":"Configuring MongoDB Connection"},{"order":15,"type":"paragraph","text":"Configure the MongoDB connection details in your `application.properties` or `application.yml` file."},{"order":16,"type":"paragraph","text":"Example `application.properties`:"},{"order":17,"type":"code","text":"spring.data.mongodb.host=localhost
spring.data.mongodb.port=27017
spring.data.mongodb.database=mydatabase"},{"order":18,"type":"paragraph","text":"Example `application.yml`:"},{"order":19,"type":"code","text":"spring:
  data:
    mongodb:
      host: localhost
      port: 27017
      database: mydatabase"},{"order":20,"type":"heading","text":"Defining Data Models"},{"order":21,"type":"paragraph","text":"Create a Java class to represent your data model. Use annotations from `org.springframework.data.mongodb.core.mapping` to map the class to a MongoDB collection."},{"order":22,"type":"code","text":"import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.mapping.Document;

@Document(collection = "products")
public class Product {

    @Id
    private String id;
    private String name;
    private String description;
    private double price;

    public Product() {}

    public Product(String name, String description, double price) {
        this.name = name;
        this.description = description;
        this.price = price;
    }

    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public double getPrice() {
        return price;
    }

    public void setPrice(double price) {
        this.price = price;
    }

    @Override
    public String toString() {
        return "Product{" +
                "id='" + id + '\'' +
                ", name='" + name + '\'' +
                ", description='" + description + '\'' +
                ", price=" + price +
                '}';
    }
}"},{"order":23,"type":"paragraph","text":"In this example:"},{"order":24,"type":"bullet_point","text":"`@Document(collection = "products")` maps the `Product` class to the 'products' collection in MongoDB."},{"order":25,"type":"bullet_point","text":"`@Id` designates the `id` field as the primary key."},{"order":26,"type":"heading","text":"Creating a Repository"},{"order":27,"type":"paragraph","text":"Create a repository interface that extends `MongoRepository`. This interface provides methods for performing CRUD operations on your data model."},{"order":28,"type":"code","text":"import org.springframework.data.mongodb.repository.MongoRepository;

public interface ProductRepository extends MongoRepository<Product, String> {
    // You can add custom query methods here if needed
}"},{"order":29,"type":"paragraph","text":"Spring Data MongoDB automatically generates the implementation for this interface."},{"order":30,"type":"heading","text":"Performing CRUD Operations"},{"order":31,"type":"subheading","text":"Creating (Saving) Data"},{"order":32,"type":"code","text":"import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.CommandLineRunner;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;

@SpringBootApplication
public class SpringDataMongodbExampleApplication {

	@Autowired
	private ProductRepository productRepository;

	public static void main(String[] args) {
		SpringApplication.run(SpringDataMongodbExampleApplication.class, args);
	}

	@Bean
	CommandLineRunner runner() {
		return args -> {
			Product product1 = new Product("Laptop", "High-performance laptop", 1200.00);
			Product product2 = new Product("Mouse", "Wireless mouse", 25.00);

			productRepository.save(product1);
			productRepository.save(product2);

			System.out.println("Products saved successfully!");
		};
	}
}"},{"order":33,"type":"subheading","text":"Reading (Retrieving) Data"},{"order":34,"type":"code","text":"// Find all products
List<Product> allProducts = productRepository.findAll();
allProducts.forEach(System.out::println);

// Find a product by ID
Optional<Product> productById = productRepository.findById("someProductId");
productById.ifPresent(System.out::println);
"},{"order":35,"type":"subheading","text":"Updating Data"},{"order":36,"type":"code","text":"Optional<Product> productToUpdate = productRepository.findById("someProductId");
productToUpdate.ifPresent(product -> {
    product.setPrice(1300.00);
    productRepository.save(product);
    System.out.println("Product updated: " + product);
});"},{"order":37,"type":"subheading","text":"Deleting Data"},{"order":38,"type":"code","text":"// Delete a product by ID
productRepository.deleteById("someProductId");
System.out.println("Product deleted successfully!");

// Delete all products
// productRepository.deleteAll();"},{"order":39,"type":"heading","text":"Custom Queries"},{"order":40,"type":"paragraph","text":"Spring Data MongoDB allows you to define custom queries using method names or `@Query` annotation."},{"order":41,"type":"subheading","text":"Query Methods"},{"order":42,"type":"paragraph","text":"You can derive queries from method names by following specific conventions. For example, to find products by name:"},{"order":43,"type":"code","text":"import java.util.List;
import org.springframework.data.mongodb.repository.MongoRepository;

public interface ProductRepository extends MongoRepository<Product, String> {
    List<Product> findByName(String name);
}"},{"order":44,"type":"code","text":"// Usage:
List<Product> productsByName = productRepository.findByName("Laptop");
productsByName.forEach(System.out::println);"},{"order":45,"type":"subheading","text":"@Query Annotation"},{"order":46,"type":"paragraph","text":"For more complex queries, you can use the `@Query` annotation to define a MongoDB query directly."},{"order":47,"type":"code","text":"import java.util.List;
import org.springframework.data.mongodb.repository.MongoRepository;
import org.springframework.data.mongodb.repository.Query;

public interface ProductRepository extends MongoRepository<Product, String> {
    @Query("{ 'price' : { $gt: ?0 } }")
    List<Product> findProductsWithPriceGreaterThan(double price);
}"},{"order":48,"type":"code","text":"// Usage:
List<Product> expensiveProducts = productRepository.findProductsWithPriceGreaterThan(1000.00);
expensiveProducts.forEach(System.out::println);"},{"order":49,"type":"heading","text":"Advanced Features"},{"order":50,"type":"subheading","text":"Indexing"},{"order":51,"type":"paragraph","text":"You can define indexes on your data model fields to improve query performance. Use the `@Indexed` annotation."},{"order":52,"type":"code","text":"import org.springframework.data.mongodb.core.index.Indexed;
import org.springframework.data.mongodb.core.mapping.Document;

@Document(collection = "products")
public class Product {
    // ... other fields

    @Indexed
    private String name;

    // ...
}"},{"order":53,"type":"subheading","text":"Auditing"},{"order":54,"type":"paragraph","text":"Spring Data MongoDB supports auditing to automatically track creation and modification timestamps. Enable auditing in your Spring Boot application and use the `@CreatedDate`, `@LastModifiedDate`, `@CreatedBy`, and `@LastModifiedBy` annotations."},{"order":55,"type":"code","text":"import org.springframework.context.annotation.Configuration;
import org.springframework.data.domain.AuditorAware;
import org.springframework.data.mongodb.config.EnableMongoAuditing;
import org.springframework.context.annotation.Bean;
import java.util.Optional;

@Configuration
@EnableMongoAuditing
public class AuditingConfiguration {

    @Bean
    public AuditorAware<String> auditorProvider() {
        return () -> Optional.of("CurrentUser"); // Replace with your actual user retrieval logic
    }
}"},{"order":56,"type":"code","text":"import java.time.LocalDateTime;
import org.springframework.data.annotation.CreatedDate;
import org.springframework.data.annotation.LastModifiedDate;
import org.springframework.data.mongodb.core.mapping.Document;

@Document(collection = "products")
public class Product {
    // ... other fields

    @CreatedDate
    private LocalDateTime createdDate;

    @LastModifiedDate
    private LocalDateTime lastModifiedDate;

    // ...
}"},{"order":57,"type":"heading","text":"Conclusion"},{"order":58,"type":"paragraph","text":"Spring Data MongoDB simplifies working with MongoDB in Spring Boot applications. It provides a powerful abstraction layer that reduces boilerplate code and allows you to focus on your business logic. This tutorial covered the basics of setting up Spring Data MongoDB, defining data models, performing CRUD operations, and exploring advanced features like custom queries and indexing. By leveraging these features, you can efficiently manage data in your NoSQL MongoDB database."}]
